input.content:
:root {
  --bg: #05090f;
  --panel: rgba(7, 17, 27, 0.93);
  --panel-soft: rgba(11, 26, 38, 0.82);
  --line: rgba(105, 226, 255, 0.25);
  --line-strong: rgba(112, 241, 255, 0.7);
  --cyan: #6df4ff;
  --cyan-soft: #35c8df;
  --cyan-deep: #08758c;
  --amber: #ffbb62;
  --danger: #ff5d6c;
  --danger-soft: #b8273c;
  --text: #dff3f7;
  --muted: #7e9ba8;
  --muted-2: #4d6b78;
  --good: #8dffbe;
  --font-display: "Bahnschrift", "DIN Alternate", "Arial Narrow", "Trebuchet MS", sans-serif;
  --font-body: "Trebuchet MS", "Segoe UI", "DejaVu Sans", sans-serif;
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-top: env(safe-area-inset-top, 0px);
}

* { box-sizing: border-box; }
html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; background: var(--bg); }
body {
  font-family: var(--font-body);
  color: var(--text);
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}
button { font: inherit; color: inherit; cursor: pointer; }
svg { display: block; }
.is-hidden { display: none !important; }
#app { position: relative; width: 100%; height: 100%; overflow: hidden; }
#game { position: absolute; inset: 0; width: 100%; height: 100%; display: block; background: #061019; cursor: crosshair; }
#game.is-commanding { cursor: cell; }
#game.is-building { cursor: copy; }

/* ===================== HUD ===================== */
#hud { position: absolute; inset: 0; pointer-events: none; opacity: 1; transition: opacity .4s ease; }
#hud > * { pointer-events: auto; }

.topbar {
  position: absolute;
  top: 0; left: 0; right: 0;
  height: calc(58px + var(--safe-top));
  padding: var(--safe-top) 18px 0;
  display: flex;
  align-items: center;
  gap: 22px;
  background:
    linear-gradient(180deg, rgba(3, 10, 17, .96), rgba(3, 11, 18, .74) 70%, transparent),
    linear-gradient(90deg, rgba(70, 231, 255, .06), transparent 24%, transparent 76%, rgba(70, 231, 255, .04));
  border-bottom: 1px solid rgba(101, 232, 255, .14);
  z-index: 10;
}
.topbar::after {
  content: "";
  position: absolute; left: 0; right: 0; bottom: -1px; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(116, 242, 255, .52) 15%, transparent 42%, transparent 58%, rgba(116, 242, 255, .35) 85%, transparent);
}
.brand { display: flex; align-items: center; gap: 12px; min-width: 250px; }
.brand-mark {
  position: relative; width: 31px; height: 31px;
  border: 1px solid rgba(111, 240, 255, .7);
  clip-path: polygon(50% 0, 100% 25%, 100% 75%, 50% 100%, 0 75%, 0 25%);
  display: grid; place-items: center;
  background: rgba(30, 202, 230, .08);
  box-shadow: inset 0 0 14px rgba(74, 236, 255, .18);
}
.brand-mark::before {
  content: ""; width: 13px; height: 13px;
  border: 1px solid var(--cyan);
  transform: rotate(45deg);
  box-shadow: 0 0 10px rgba(102, 241, 255, .65);
}
.brand-mark span { position: absolute; width: 4px; height: 4px; background: var(--cyan); border-radius: 50%; box-shadow: 0 0 8px var(--cyan); }
.brand-text { display: flex; flex-direction: column; line-height: 1; }
.brand-text strong { font-family: var(--font-display); font-size: 17px; letter-spacing: .24em; font-weight: 700; color: #effdff; }
.brand-text small { margin-top: 5px; font-size: 8px; letter-spacing: .17em; color: var(--muted); }

.resource-strip { display: flex; align-items: center; gap: 7px; flex: 1; justify-content: center; }
.resource {
  display: flex; align-items: center; gap: 7px;
  min-width: 138px; height: 34px; padding: 0 12px;
  background: linear-gradient(180deg, rgba(17, 43, 57, .55), rgba(4, 14, 23, .55));
  border: 1px solid rgba(110, 230, 255, .16);
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
  color: var(--cyan);
}
.resource svg { width: 17px; height: 17px; opacity: .9; }
.resource-value { font-family: var(--font-display); font-size: 17px; font-weight: 700; color: #ecfdff; letter-spacing: .04em; min-width: 36px; }
.resource-label { font-size: 7.5px; letter-spacing: .16em; color: var(--muted); margin-left: 1px; }
.resource.warning { border-color: rgba(255, 93, 108, .48); }
.resource.warning .resource-value { color: var(--danger); }
.resource.workers-resource { min-width: 145px; color: var(--muted); }
.resource.workers-resource .resource-value { color: #d5f5fa; }

.top-actions { display: flex; align-items: center; gap: 8px; min-width: 210px; justify-content: flex-end; }
.mission-clock { display: flex; flex-direction: column; align-items: flex-end; margin-right: 7px; }
.mission-clock span { font-family: var(--font-display); font-size: 16px; letter-spacing: .13em; color: #effcff; }
.mission-clock small { color: var(--muted-2); font-size: 7px; letter-spacing: .18em; margin-top: 2px; }
.icon-button {
  width: 32px; height: 32px; padding: 7px;
  display: grid; place-items: center;
  background: rgba(17, 42, 54, .35);
  border: 1px solid rgba(106, 224, 255, .2);
  color: var(--muted);
  transition: .16s ease;
}
.icon-button:hover { color: var(--cyan); border-color: rgba(106, 224, 255, .6); background: rgba(46, 196, 222, .1); }
.icon-button svg { width: 100%; height: 100%; }
#sound-button .sound-off { display: none; }
#sound-button.muted .sound-on { display: none; }
#sound-button.muted .sound-off { display: block; }

.objective-panel {
  position: absolute; top: calc(77px + var(--safe-top)); left: 18px; width: 294px;
  padding: 13px 15px 12px;
  background: linear-gradient(145deg, rgba(9, 25, 37, .91), rgba(5, 14, 22, .75));
  border: 1px solid rgba(105, 227, 255, .17);
  border-left: 2px solid rgba(105, 227, 255, .65);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%);
  z-index: 5;
  backdrop-filter: blur(4px);
}
.panel-kicker { display: flex; align-items: center; gap: 7px; font-family: var(--font-display); font-size: 8px; letter-spacing: .2em; color: var(--cyan-soft); }
.pulse-dot { width: 5px; height: 5px; background: var(--cyan); border-radius: 50%; box-shadow: 0 0 8px var(--cyan); animation: pulse 1.8s infinite; }
@keyframes pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: .45; transform: scale(.7); } }
.objective-title { margin-top: 7px; font-family: var(--font-display); font-size: 15px; letter-spacing: .055em; color: #edfbff; text-transform: uppercase; }
.objective-sub { margin-top: 4px; font-size: 10.5px; color: var(--muted); line-height: 1.45; }
.objective-progress { height: 2px; margin-top: 10px; background: rgba(110, 230, 255, .13); overflow: hidden; }
.objective-progress i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #28bcd4, #9df9ff); transition: width .4s ease; box-shadow: 0 0 8px var(--cyan); }
.threat-row { display: flex; align-items: center; gap: 9px; margin-top: 9px; font-family: var(--font-display); font-size: 7.5px; letter-spacing: .17em; color: var(--muted-2); }
.threat-pips { display: flex; gap: 3px; flex: 1; }
.threat-pips i { flex: 1; height: 3px; background: rgba(110, 230, 255, .13); }
.threat-pips i.on { background: var(--danger); box-shadow: 0 0 5px rgba(255, 93, 108, .5); }
.threat-row span:last-child { color: var(--amber); min-width: 32px; text-align: right; }

.alert-stack { position: absolute; top: calc(76px + var(--safe-top)); left: 50%; transform: translateX(-50%); width: min(410px, 50vw); display: flex; flex-direction: column; align-items: center; gap: 6px; z-index: 30; pointer-events: none; }
.alert {
  display: flex; align-items: center; gap: 9px;
  padding: 8px 16px; max-width: 100%;
  color: #e9fdff; font-size: 11px; letter-spacing: .05em;
  background: rgba(6, 20, 30, .9);
  border: 1px solid rgba(105, 228, 255, .3);
  box-shadow: 0 6px 22px rgba(0, 0, 0, .35);
  animation: alertIn .24s ease both;
  clip-path: polygon(7px 0, 100% 0, 100% calc(100% - 7px), calc(100% - 7px) 100%, 0 100%, 0 7px);
}
.alert::before { content: ""; width: 5px; height: 5px; background: var(--cyan); box-shadow: 0 0 7px var(--cyan); }
.alert.danger { border-color: rgba(255, 93, 108, .55); color: #ffe9eb; }
.alert.danger::before { background: var(--danger); box-shadow: 0 0 7px var(--danger); }
.alert.good { border-color: rgba(141, 255, 190, .45); }
.alert.good::before { background: var(--good); box-shadow: 0 0 7px var(--good); }
.alert.out { animation: alertOut .25s ease both; }
@keyframes alertIn { from { opacity: 0; transform: translateY(-8px); } }
@keyframes alertOut { to { opacity: 0; transform: translateY(-8px); } }

.notification-panel {
  position: absolute; top: calc(82px + var(--safe-top)); right: 18px;
  display: flex; align-items: center; gap: 10px;
  max-width: 290px; padding: 9px 13px;
  background: rgba(8, 22, 32, .88);
  border: 1px solid rgba(255, 187, 98, .25);
  border-right: 2px solid rgba(255, 187, 98, .7);
  z-index: 12; opacity: 0; transform: translateX(12px); transition: .28s ease; pointer-events: none;
}
.notification-panel.show { opacity: 1; transform: translateX(0); }
.notification-icon {
  width: 23px; height: 23px; display: grid; place-items: center; flex: none;
  border: 1px solid rgba(255, 187, 98, .6); color: var(--amber);
  font-family: var(--font-display); font-weight: 700; font-size: 12px;
  transform: rotate(45deg);
}
.notification-icon::before { content: ""; }
.notification-panel strong { display: block; font-family: var(--font-display); font-size: 9px; letter-spacing: .15em; color: var(--amber); }
.notification-panel span { display: block; margin-top: 2px; font-size: 10px; color: var(--muted); }

/* ===================== BOTTOM PANEL ===================== */
.bottom-panel {
  position: absolute; left: 0; right: 0; bottom: 0;
  height: calc(172px + var(--safe-bottom));
  padding: 0 16px var(--safe-bottom);
  display: grid; grid-template-columns: minmax(280px, 1.1fr) minmax(210px, .72fr) minmax(330px, 1.15fr);
  gap: 8px;
  background:
    linear-gradient(180deg, transparent, rgba(4, 11, 18, .52) 8%, rgba(4, 12, 19, .9) 28%, rgba(3, 9, 15, .98)),
    radial-gradient(ellipse at 50% 100%, rgba(28, 153, 177, .12), transparent 65%);
  border-top: 1px solid rgba(110, 233, 255, .13);
  z-index: 12;
}
.bottom-panel::before {
  content: ""; position: absolute; top: -1px; left: 8%; right: 8%; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(111, 241, 255, .55), transparent);
}
.selection-panel, .center-panel, .command-panel { min-width: 0; }
.selection-panel { display: flex; gap: 11px; padding: 12px 0 0 4px; min-width: 0; }
.portrait-frame {
  position: relative; width: 122px; height: 122px; flex: none;
  border: 1px solid rgba(110, 231, 255, .23);
  background: radial-gradient(circle at 50% 40%, rgba(31, 133, 155, .19), rgba(4, 14, 22, .88) 70%);
  overflow: hidden;
}
.portrait-frame::before { content: ""; position: absolute; inset: 7px; border: 1px solid rgba(112, 237, 255, .08); }
.portrait-frame::after { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 1px; background: linear-gradient(90deg, transparent, var(--cyan), transparent); opacity: .6; }
#portrait { width: 100%; height: 100%; }
.portrait-corner { position: absolute; width: 13px; height: 13px; border-color: var(--cyan); border-style: solid; opacity: .85; }
.portrait-corner.tl { top: 0; left: 0; border-width: 2px 0 0 2px; }
.portrait-corner.br { right: 0; bottom: 0; border-width: 0 2px 2px 0; }
.selection-details { flex: 1; min-width: 0; padding-top: 1px; display: flex; flex-direction: column; }
.selection-heading { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; }
.selection-heading h2 { margin: 0; font-family: var(--font-display); font-size: 18px; letter-spacing: .08em; color: #f0fdff; text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.selection-heading p { margin: 3px 0 0; font-size: 9px; letter-spacing: .12em; color: var(--muted); text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.team-tag { font-family: var(--font-display); font-size: 7px; letter-spacing: .14em; padding: 3px 5px; border: 1px solid rgba(109, 244, 255, .3); color: var(--cyan); flex: none; }
.team-tag.enemy { border-color: rgba(255, 93, 108, .45); color: var(--danger); }
.health-block { margin-top: 13px; }
.health-label { display: flex; justify-content: space-between; align-items: baseline; font-family: var(--font-display); font-size: 7px; letter-spacing: .16em; color: var(--muted-2); }
.health-label b { color: #e9fbff; font-size: 10px; font-weight: 600; letter-spacing: .07em; }
.health-track { height: 5px; margin-top: 4px; background: rgba(111, 230, 255, .1); overflow: hidden; }
.health-track i { display: block; width: 100%; height: 100%; background: linear-gradient(90deg, #3bd6df, #9bffd1); box-shadow: 0 0 8px rgba(92, 255, 205, .4); transition: width .2s ease; }
.health-track i.low { background: linear-gradient(90deg, #d34a42, #ff9d5e); }
.health-track i.enemy { background: linear-gradient(90deg, #d12742, #ff825f); }
.stat-row { display: flex; gap: 13px; margin-top: 9px; flex-wrap: wrap; }
.stat { display: flex; flex-direction: column; gap: 2px; }
.stat span { font-size: 6.5px; letter-spacing: .14em; color: var(--muted-2); }
.stat b { font-family: var(--font-display); font-size: 10.5px; color: #cbeaf0; font-weight: 600; }
.queue-row { display: flex; gap: 4px; margin-top: auto; padding-top: 8px; min-height: 31px; }
.queue-chip { position: relative; width: 28px; height: 28px; border: 1px solid rgba(105, 230, 255, .24); background: rgba(14, 47, 60, .24); overflow: hidden; }
.queue-chip canvas { width: 100%; height: 100%; }
.queue-chip i { position: absolute; left: 0; bottom: 0; height: 2px; background: var(--cyan); }
.queue-chip .queue-cancel { position: absolute; inset: 0; display: grid; place-items: center; background: rgba(6, 14, 20, .5); color: var(--danger); font-size: 15px; opacity: 0; transition: .15s; }
.queue-chip:hover .queue-cancel { opacity: 1; }
.queue-label { font-size: 8px; color: var(--muted); align-self: center; letter-spacing: .1em; }

.center-panel { padding-top: 9px; display: flex; flex-direction: column; align-items: center; min-height: 0; }
.sensor-head { width: 100%; display: flex; justify-content: space-between; font-family: var(--font-display); font-size: 7px; letter-spacing: .15em; color: var(--muted-2); padding: 0 2px 5px; }
.minimap-shell { position: relative; width: 100%; max-width: 278px; aspect-ratio: 16 / 10; border: 1px solid rgba(110, 230, 255, .24); background: #030c13; overflow: hidden; box-shadow: inset 0 0 25px rgba(0, 0, 0, .6), 0 0 18px rgba(15, 122, 145, .08); }
#minimap { width: 100%; height: 100%; display: block; }
.minimap-corners i { position: absolute; width: 7px; height: 7px; border-color: rgba(111, 241, 255, .8); border-style: solid; }
.minimap-corners i:nth-child(1) { top: 0; left: 0; border-width: 1px 0 0 1px; }
.minimap-corners i:nth-child(2) { top: 0; right: 0; border-width: 1px 1px 0 0; }
.minimap-corners i:nth-child(3) { bottom: 0; left: 0; border-width: 0 0 1px 1px; }
.minimap-corners i:nth-child(4) { bottom: 0; right: 0; border-width: 0 1px 1px 0; }
.minimap-scan { position: absolute; inset: 0; pointer-events: none; background: linear-gradient(180deg, transparent, rgba(106, 239, 255, .07) 49%, rgba(106, 239, 255, .18) 50%, transparent 51%); background-size: 100% 40px; animation: scan 5s linear infinite; mix-blend-mode: screen; }
@keyframes scan { from { background-position: 0 -40px; } to { background-position: 0 220px; } }
.center-footer { width: 100%; max-width: 278px; display: flex; justify-content: space-between; padding-top: 5px; font-family: var(--font-display); font-size: 7px; letter-spacing: .12em; color: var(--muted-2); }
.key-hint { color: var(--muted-2); font-family: var(--font-display); font-size: 7px; letter-spacing: .1em; }

.command-panel { padding: 12px 4px 0 0; display: flex; flex-direction: column; }
.command-head { display: flex; justify-content: space-between; align-items: baseline; padding: 0 2px 7px; }
.command-head > span:first-child { font-family: var(--font-display); font-size: 8px; letter-spacing: .18em; color: var(--cyan-soft); }
.command-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; }
.command-button {
  position: relative; min-height: 57px; padding: 5px 6px 4px;
  display: flex; flex-direction: column; align-items: flex-start; justify-content: center;
  background: linear-gradient(145deg, rgba(15, 43, 57, .66), rgba(5, 17, 27, .72));
  border: 1px solid rgba(103, 222, 246, .17);
  color: #ccebf0; text-align: left; overflow: hidden;
  clip-path: polygon(6px 0, 100% 0, 100% calc(100% - 6px), calc(100% - 6px) 100%, 0 100%, 0 6px);
  transition: border-color .14s ease, background .14s ease, transform .1s ease;
}
.command-button:hover { border-color: rgba(113, 241, 255, .58); background: linear-gradient(145deg, rgba(24, 69, 85, .7), rgba(7, 26, 38, .85)); }
.command-button:active { transform: translateY(1px); }
.command-button.disabled { opacity: .36; cursor: not-allowed; filter: grayscale(.35); }
.command-button .cmd-icon { width: 26px; height: 26px; margin-bottom: 2px; color: var(--cyan); }
.command-button .cmd-icon svg { width: 100%; height: 100%; }
.command-button strong { font-family: var(--font-display); font-size: 8px; letter-spacing: .09em; font-weight: 600; text-transform: uppercase; line-height: 1.1; }
.command-button small { margin-top: 2px; font-size: 7px; color: var(--muted-2); letter-spacing: .06em; }
.command-button .hotkey { position: absolute; right: 4px; top: 3px; font-family: var(--font-display); font-size: 7px; color: var(--muted); border: 1px solid rgba(110, 230, 255, .17); padding: 1px 3px; }
.command-button .cost { color: var(--amber); }
.command-button .queue-count { position: absolute; right: 5px; bottom: 4px; font-family: var(--font-display); font-size: 10px; color: var(--cyan); }
.command-button.toggled { border-color: rgba(255, 93, 108, .65); background: rgba(83, 22, 31, .55); }
.command-empty { grid-column: 1 / -1; min-height: 57px; display: flex; align-items: center; justify-content: center; border: 1px dashed rgba(105, 230, 255, .12); color: var(--muted-2); font-family: var(--font-display); font-size: 8px; letter-spacing: .15em; }
.command-footer { margin-top: auto; display: flex; align-items: center; justify-content: space-between; gap: 8px; min-height: 21px; border-top: 1px solid rgba(110, 233, 255, .08); padding-top: 5px; }
.mineral-mini { display: flex; align-items: center; gap: 5px; color: var(--amber); font-family: var(--font-display); font-size: 11px; }
.mineral-mini svg { width: 11px; height: 11px; }
.command-hint { font-size: 8px; letter-spacing: .05em; color: var(--muted-2); text-align: right; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.command-hint.warn { color: var(--danger); }

.control-hint-bar { position: absolute; left: 50%; bottom: calc(175px + var(--safe-bottom)); transform: translateX(-50%); display: flex; gap: 14px; padding: 4px 12px; background: rgba(4, 13, 20, .74); border: 1px solid rgba(106, 228, 255, .1); font-family: var(--font-display); font-size: 7px; letter-spacing: .11em; color: var(--muted-2); opacity: .8; z-index: 4; white-space: nowrap; }
.control-hint-bar b { color: var(--muted); font-weight: 600; }

.mobile-controls { display: none; }

/* ===================== OVERLAYS ===================== */
.overlay { position: absolute; inset: 0; z-index: 60; display: flex; align-items: center; justify-content: center; }
.menu-overlay { background: radial-gradient(circle at 72% 38%, rgba(16, 77, 96, .24), transparent 44%), radial-gradient(circle at 20% 80%, rgba(49, 26, 55, .18), transparent 50%), rgba(2, 8, 13, .88); overflow: hidden; }
.menu-grid { position: absolute; inset: -20%; opacity: .24; background-image: linear-gradient(rgba(91, 219, 242, .12) 1px, transparent 1px), linear-gradient(90deg, rgba(91, 219, 242, .12) 1px, transparent 1px); background-size: 56px 56px; transform: perspective(700px) rotateX(62deg) translateY(24%); mask-image: radial-gradient(ellipse at 50% 60%, #000 20%, transparent 72%); }
.menu-grid::after { content: ""; position: absolute; inset: 0; background-image: linear-gradient(rgba(126, 241, 255, .22) 1px, transparent 1px); background-size: 280px 280px; }
.menu-frame { position: relative; width: min(1160px, calc(100vw - 64px)); min-height: 620px; max-height: calc(100vh - 44px); display: flex; flex-direction: column; border: 1px solid rgba(104, 233, 255, .17); background: linear-gradient(135deg, rgba(5, 17, 25, .92), rgba(3, 10, 17, .85)); box-shadow: 0 28px 100px rgba(0, 0, 0, .52), inset 0 0 80px rgba(20, 111, 132, .05); clip-path: polygon(18px 0, 100% 0, 100% calc(100% - 18px), calc(100% - 18px) 100%, 0 100%, 0 18px); backdrop-filter: blur(10px); }
.menu-frame::before, .menu-frame::after { content: ""; position: absolute; width: 76px; height: 1px; background: var(--cyan); opacity: .65; }
.menu-frame::before { top: -1px; left: 18px; }
.menu-frame::after { bottom: -1px; right: 18px; }
.menu-topline { display: flex; justify-content: space-between; padding: 14px 28px; border-bottom: 1px solid rgba(105, 229, 255, .1); font-family: var(--font-display); font-size: 8px; letter-spacing: .18em; color: var(--muted-2); }
.transmission { color: var(--cyan-soft); }
.transmission i { display: inline-block; width: 5px; height: 5px; margin-right: 5px; border-radius: 50%; background: var(--good); box-shadow: 0 0 8px var(--good); }
.menu-content { flex: 1; display: grid; grid-template-columns: 1fr 340px; gap: 34px; padding: 30px 42px 22px; align-items: center; min-height: 0; }
.title-block { min-width: 0; }
.eyebrow { font-family: var(--font-display); font-size: 10px; letter-spacing: .45em; color: var(--cyan-soft); margin-bottom: 15px; display: flex; align-items: center; gap: 12px; }
.eyebrow::before { content: ""; width: 36px; height: 1px; background: var(--cyan-soft); }
.title-block h1 { margin: 0; font-family: var(--font-display); font-weight: 700; line-height: .83; letter-spacing: .02em; text-transform: uppercase; }
.title-block h1 span { display: block; font-size: clamp(54px, 8vw, 104px); color: #eefdff; text-shadow: 0 0 34px rgba(104, 239, 255, .18); }
.title-block h1 b { display: block; font-size: clamp(31px, 4.8vw, 67px); font-weight: 300; letter-spacing: .34em; color: var(--cyan); text-shadow: 0 0 20px rgba(95, 231, 255, .3); }
.tagline { max-width: 520px; margin: 23px 0 0; color: var(--muted); font-size: 12px; line-height: 1.7; letter-spacing: .03em; }
.title-rule { display: flex; align-items: center; gap: 10px; margin: 19px 0 20px; color: var(--muted-2); font-family: var(--font-display); font-size: 8px; letter-spacing: .3em; }
.title-rule i { flex: 1; height: 1px; background: linear-gradient(90deg, rgba(105, 229, 255, .25), transparent); }
.title-rule i:last-child { background: linear-gradient(90deg, transparent, rgba(105, 229, 255, .25)); }
.difficulty-label { font-family: var(--font-display); font-size: 8px; letter-spacing: .22em; color: var(--muted-2); margin-bottom: 8px; }
.difficulty-picker { display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px; }
.difficulty-picker button { position: relative; padding: 11px 11px 12px; text-align: left; background: rgba(11, 31, 43, .4); border: 1px solid rgba(105, 229, 255, .12); color: var(--muted); transition: .18s ease; clip-path: polygon(6px 0, 100% 0, 100% calc(100% - 6px), calc(100% - 6px) 100%, 0 100%, 0 6px); }
.difficulty-picker button:hover { border-color: rgba(105, 229, 255, .36); color: var(--text); }
.difficulty-picker button.active { border-color: rgba(109, 244, 255, .6); background: linear-gradient(145deg, rgba(31, 114, 133, .25), rgba(8, 28, 40, .6)); color: var(--text); box-shadow: inset 0 0 25px rgba(55, 205, 230, .08); }
.difficulty-picker button.active::before { content: ""; position: absolute; top: 0; left: 0; width: 22px; height: 2px; background: var(--cyan); }
.difficulty-picker small { display: block; font-family: var(--font-display); font-size: 7px; letter-spacing: .12em; color: var(--muted-2); margin-bottom: 5px; }
.difficulty-picker strong { display: block; font-family: var(--font-display); font-size: 12px; letter-spacing: .13em; font-weight: 600; }
.difficulty-picker span { display: block; margin-top: 4px; font-size: 8px; line-height: 1.35; color: var(--muted-2); }
.deploy-button { width: 100%; margin-top: 13px; height: 48px; display: flex; align-items: center; justify-content: space-between; padding: 0 18px 0 22px; border: 1px solid rgba(110, 242, 255, .72); background: linear-gradient(90deg, rgba(25, 150, 173, .33), rgba(24, 75, 91, .2)); color: #effdff; font-family: var(--font-display); font-size: 12px; letter-spacing: .22em; clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 10px 100%, 0 calc(100% - 10px)); transition: .18s ease; position: relative; overflow: hidden; }
.deploy-button::before { content: ""; position: absolute; inset: 0; background: linear-gradient(110deg, transparent 20%, rgba(153, 252, 255, .18), transparent 60%); transform: translateX(-100%); transition: transform .5s ease; }
.deploy-button:hover { background: linear-gradient(90deg, rgba(38, 195, 216, .42), rgba(28, 99, 117, .32)); box-shadow: 0 0 25px rgba(63, 221, 241, .14); }
.deploy-button:hover::before { transform: translateX(100%); }
.deploy-button svg { width: 19px; height: 19px; }
.menu-meta { display: flex; justify-content: space-between; gap: 10px; margin-top: 9px; font-family: var(--font-display); font-size: 6.5px; letter-spacing: .13em; color: var(--muted-2); }

.briefing-card { position: relative; align-self: stretch; display: flex; flex-direction: column; margin: 6px 0; padding: 15px; border: 1px solid rgba(105, 229, 255, .18); background: linear-gradient(155deg, rgba(12, 35, 47, .65), rgba(4, 13, 21, .75)); clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 14px 100%, 0 calc(100% - 14px)); }
.briefing-card::before { content: ""; position: absolute; top: 0; right: 14px; width: 80px; height: 1px; background: var(--cyan); opacity: .6; }
.briefing-header { display: flex; justify-content: space-between; align-items: center; font-family: var(--font-display); font-size: 8px; letter-spacing: .18em; color: var(--cyan-soft); }
.briefing-header b { font-size: 20px; font-weight: 300; color: rgba(110, 239, 255, .35); }
.holo-map { position: relative; height: 170px; margin: 12px 0; background: radial-gradient(circle at 50% 50%, rgba(32, 160, 178, .13), transparent 62%), linear-gradient(rgba(88, 225, 246, .04) 1px, transparent 1px), linear-gradient(90deg, rgba(88, 225, 246, .04) 1px, transparent 1px); background-size: 100% 100%, 18px 18px, 18px 18px; border: 1px solid rgba(94, 227, 248, .1); overflow: hidden; }
.holo-ring { position: absolute; left: 50%; top: 50%; border: 1px solid rgba(101, 234, 255, .16); border-radius: 50%; transform: translate(-50%, -50%); }
.holo-ring.r1 { width: 138px; height: 138px; }
.holo-ring.r2 { width: 96px; height: 96px; border-style: dashed; animation: spin 24s linear infinite; }
.holo-ring.r3 { width: 47px; height: 47px; border-color: rgba(101, 234, 255, .28); }
@keyframes spin { to { transform: translate(-50%, -50%) rotate(360deg); } }
.holo-sweep { position: absolute; left: 50%; top: 50%; width: 70px; height: 70px; transform-origin: 0 0; background: conic-gradient(from 0deg, rgba(103, 240, 255, .22), transparent 30%); animation: spinSweep 5s linear infinite; }
@keyframes spinSweep { to { transform: rotate(360deg); } }
.holo-axis { position: absolute; background: rgba(101, 234, 255, .12); }
.holo-axis.x { left: 12%; right: 12%; top: 50%; height: 1px; }
.holo-axis.y { top: 12%; bottom: 12%; left: 50%; width: 1px; }
.holo-base { position: absolute; width: 25px; height: 25px; display: grid; place-items: center; font-family: var(--font-display); font-size: 8px; letter-spacing: .1em; border: 1px solid; border-radius: 50%; background: rgba(2, 12, 18, .75); }
.holo-base.player { left: 19%; top: 55%; color: var(--cyan); border-color: rgba(106, 240, 255, .7); box-shadow: 0 0 16px rgba(70, 226, 250, .2); }
.holo-base.enemy { right: 16%; top: 35%; color: var(--danger); border-color: rgba(255, 93, 108, .7); box-shadow: 0 0 16px rgba(255, 74, 94, .14); }
.holo-blip { position: absolute; width: 4px; height: 4px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 7px var(--cyan); }
.holo-blip.b1 { left: 35%; top: 42%; }
.holo-blip.b2 { right: 32%; top: 64%; background: var(--danger); box-shadow: 0 0 7px var(--danger); }
.holo-blip.b3 { left: 58%; top: 28%; background: var(--danger); box-shadow: 0 0 7px var(--danger); }
.briefing-copy { flex: 1; display: flex; flex-direction: column; }
.brief-row { display: flex; flex-direction: column; gap: 4px; padding-bottom: 10px; border-bottom: 1px solid rgba(106, 231, 255, .1); }
.brief-row span { font-family: var(--font-display); font-size: 7px; letter-spacing: .18em; color: var(--muted-2); }
.brief-row b { font-family: var(--font-display); font-size: 11px; letter-spacing: .08em; color: var(--amber); }
.briefing-copy p { margin: 10px 0 8px; color: var(--muted); font-size: 9.5px; line-height: 1.55; }
.briefing-copy ul { margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 5px; }
.briefing-copy li { display: flex; gap: 7px; align-items: flex-start; font-size: 8.5px; color: var(--muted-2); line-height: 1.3; }
.briefing-copy li i { width: 4px; height: 4px; margin-top: 4px; background: var(--cyan); box-shadow: 0 0 5px var(--cyan); flex: none; }
.briefing-footer { margin-top: 12px; padding-top: 9px; border-top: 1px solid rgba(106, 231, 255, .1); display: flex; justify-content: space-between; font-family: var(--font-display); font-size: 6.5px; letter-spacing: .12em; color: var(--muted-2); }
.briefing-footer .code { color: var(--cyan-soft); }
.controls-strip { display: grid; grid-template-columns: repeat(6, 1fr); gap: 1px; border-top: 1px solid rgba(105, 229, 255, .11); background: rgba(105, 229, 255, .06); }
.controls-strip > div { padding: 10px 13px; background: rgba(3, 11, 18, .94); display: flex; flex-direction: column; gap: 3px; }
.controls-strip b { font-family: var(--font-display); font-size: 6.5px; letter-spacing: .16em; color: var(--cyan-soft); font-weight: 500; }
.controls-strip span { font-size: 8px; color: var(--muted-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.compact-overlay { background: rgba(1, 6, 10, .78); backdrop-filter: blur(7px); }
.modal-card { width: min(520px, calc(100vw - 38px)); padding: 34px 38px; text-align: center; background: linear-gradient(145deg, rgba(10, 27, 39, .97), rgba(4, 13, 20, .98)); border: 1px solid rgba(108, 236, 255, .26); box-shadow: 0 30px 90px rgba(0, 0, 0, .6), inset 0 0 80px rgba(34, 158, 181, .05); clip-path: polygon(16px 0, 100% 0, 100% calc(100% - 16px), calc(100% - 16px) 100%, 0 100%, 0 16px); position: relative; }
.modal-card::before { content: ""; position: absolute; top: 0; left: 16px; width: 100px; height: 1px; background: var(--cyan); }
.modal-card .panel-kicker { justify-content: center; }
.modal-card h2 { margin: 11px 0 7px; font-family: var(--font-display); font-size: clamp(24px, 3.5vw, 38px); letter-spacing: .13em; color: #effdff; font-weight: 600; }
.modal-card p { margin: 0 auto; max-width: 380px; color: var(--muted); font-size: 11px; line-height: 1.6; }
.modal-actions { display: flex; flex-direction: column; gap: 7px; margin-top: 22px; }
.modal-actions button { height: 40px; border: 1px solid rgba(106, 228, 255, .23); background: rgba(12, 40, 52, .3); color: var(--text); font-family: var(--font-display); font-size: 9px; letter-spacing: .2em; transition: .16s; }
.modal-actions button:hover { border-color: rgba(106, 228, 255, .6); background: rgba(22, 82, 99, .3); }
.modal-actions button.primary { border-color: rgba(110, 242, 255, .65); background: linear-gradient(90deg, rgba(29, 157, 179, .35), rgba(17, 72, 87, .25)); color: #effdff; }
.end-card { width: min(580px, calc(100vw - 38px)); }
.end-chevrons { display: flex; justify-content: center; gap: 9px; margin-bottom: 13px; }
.end-chevrons i { width: 18px; height: 5px; background: var(--cyan); transform: skewX(-30deg); box-shadow: 0 0 10px rgba(106, 239, 255, .5); animation: chev 1s ease-in-out infinite alternate; }
.end-chevrons i:nth-child(2) { animation-delay: .12s; opacity: .7; }
.end-chevrons i:nth-child(3) { animation-delay: .24s; opacity: .4; }
@keyframes chev { to { transform: skewX(-30deg) translateX(5px); } }
.end-card.defeat .end-chevrons i { background: var(--danger); box-shadow: 0 0 10px rgba(255, 93, 108, .5); }
.end-card.defeat::before { background: var(--danger); }
.end-card.defeat .panel-kicker { color: var(--danger); }
.end-stats { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1px; margin-top: 22px; background: rgba(106, 230, 255, .13); border: 1px solid rgba(106, 230, 255, .13); text-align: left; }
.end-stat { display: flex; justify-content: space-between; align-items: baseline; padding: 10px 13px; background: rgba(4, 14, 21, .9); }
.end-stat span { font-family: var(--font-display); font-size: 7px; letter-spacing: .15em; color: var(--muted-2); }
.end-stat b { font-family: var(--font-display); font-size: 15px; color: var(--cyan); font-weight: 500; }
.loading { position: absolute; bottom: 18px; left: 50%; transform: translateX(-50%); font-family: var(--font-display); font-size: 8px; letter-spacing: .2em; color: var(--muted-2); display: flex; align-items: center; gap: 8px; z-index: 80; }
.loading span { width: 10px; height: 10px; border: 1px solid var(--cyan); border-top-color: transparent; border-radius: 50%; animation: spin 1s linear infinite; }

/* tooltip */
#tooltip { position: fixed; z-index: 100; max-width: 240px; padding: 8px 10px; pointer-events: none; background: rgba(4, 14, 22, .97); border: 1px solid rgba(106, 230, 255, .3); color: var(--muted); font-size: 9px; line-height: 1.45; opacity: 0; transform: translateY(4px); transition: .12s ease; }
#tooltip.show { opacity: 1; transform: translateY(0); }
#tooltip b { display: block; margin-bottom: 2px; color: var(--text); font-family: var(--font-display); font-size: 9px; letter-spacing: .12em; }
#tooltip .tt-cost { display: flex; gap: 8px; margin-top: 4px; color: var(--amber); font-family: var(--font-display); font-size: 8px; }
#tooltip .tt-warn { color: var(--danger); margin-top: 3px; }

/* ===================== RESPONSIVE ===================== */
@media (max-width: 1120px) {
  .brand { min-width: 190px; }
  .brand-text small { display: none; }
  .resource { min-width: 110px; }
  .resource-label { display: none; }
  .resource.workers-resource { min-width: 80px; }
  .top-actions { min-width: 160px; }
  .bottom-panel { grid-template-columns: minmax(235px, 1.05fr) minmax(180px, .62fr) minmax(290px, 1.1fr); }
  .portrait-frame { width: 104px; height: 104px; }
  .selection-heading h2 { font-size: 15px; }
  .command-button { min-height: 54px; }
