}
@media (max-width: 900px) {
  .brand { min-width: 0; flex: 1; }
  .brand-text strong { font-size: 14px; }
  .resource-strip { gap: 4px; }
  .resource { min-width: 91px; height: 31px; padding: 0 8px; }
  .resource-value { font-size: 14px; min-width: 28px; }
  .mission-clock { display: none; }
  .top-actions { min-width: 0; flex: none; }
  .objective-panel { width: 250px; padding: 10px 12px; }
  .objective-title { font-size: 12px; }
  .objective-sub { font-size: 9px; }
  .bottom-panel { height: calc(148px + var(--safe-bottom)); grid-template-columns: minmax(210px, 1fr) 180px minmax(260px, 1fr); }
  .portrait-frame { width: 88px; height: 88px; }
  .selection-panel { padding-top: 9px; }
  .health-block { margin-top: 8px; }
  .stat-row { gap: 8px; margin-top: 6px; }
  .stat span { font-size: 5.8px; }
  .stat b { font-size: 9px; }
  .center-panel { padding-top: 6px; }
  .command-panel { padding-top: 8px; }
  .command-button { min-height: 48px; padding: 3px 5px; }
  .command-button .cmd-icon { width: 19px; height: 19px; }
  .command-button strong { font-size: 7px; }
  .command-button small { display: none; }
  .command-empty { min-height: 48px; }
  .command-grid { gap: 4px; }
