  .selection-panel { display: none; }
  .center-panel { display: block; position: absolute; right: 7px; bottom: calc(99px + var(--safe-bottom)); width: 118px; padding: 0; }
  .sensor-head, .center-footer { display: none; }
  .minimap-shell { width: 118px; aspect-ratio: 16/10; border-color: rgba(110, 230, 255, .35); }
  .command-panel { grid-row: 2; padding: 4px 0 0; }
  .command-head { padding: 0 2px 4px; }
  .command-head > span:first-child { font-size: 7px; }
  .command-grid { grid-template-columns: repeat(5, 1fr); gap: 4px; }
  .command-button { min-height: 54px; align-items: center; justify-content: center; text-align: center; padding: 3px; }
  .command-button .cmd-icon { width: 18px; height: 18px; margin: 0 0 2px; }
  .command-button strong { font-size: 6.5px; letter-spacing: .04em; line-height: 1.1; }
  .command-button .hotkey { font-size: 6px; top: 2px; right: 2px; }
  .command-button .queue-count { bottom: 1px; right: 2px; font-size: 7px; }
  .command-empty { grid-column: 1 / -1; min-height: 54px; }
  .command-footer { display: none; }
  .mobile-controls { display: flex; position: absolute; left: 7px; bottom: calc(101px + var(--safe-bottom)); gap: 4px; z-index: 15; }
  .mobile-controls button { height: 28px; padding: 0 9px; background: rgba(5, 19, 28, .9); border: 1px solid rgba(106, 230, 255, .27); color: var(--muted); font-family: var(--font-display); font-size: 7px; letter-spacing: .11em; }
  .mobile-controls button:active { background: rgba(28, 105, 122, .4); color: var(--cyan); }
  .menu-frame { width: calc(100vw - 18px); min-height: 0; max-height: calc(100vh - 18px); overflow-y: auto; }
  .menu-topline { padding: 10px 14px; font-size: 6.5px; }
  .menu-content { grid-template-columns: 1fr; gap: 18px; padding: 20px 18px; align-items: start; }
  .title-block h1 span { font-size: clamp(46px, 15vw, 72px); }
  .title-block h1 b { font-size: clamp(24px, 8vw, 40px); letter-spacing: .26em; }
  .tagline { margin-top: 15px; font-size: 10px; }
  .title-rule { margin: 13px 0; }
  .difficulty-picker { gap: 4px; }
  .difficulty-picker button { padding: 8px 7px; }
  .difficulty-picker span { display: none; }
  .difficulty-picker strong { font-size: 9px; }
  .deploy-button { height: 42px; margin-top: 9px; font-size: 10px; }
  .briefing-card { margin: 0; padding: 11px; }
  .holo-map { height: 105px; margin: 8px 0; }
  .briefing-copy p { display: none; }
  .briefing-copy ul { display: none; }
  .briefing-footer { margin-top: 8px; padding-top: 7px; }
  .controls-strip { grid-template-columns: repeat(3, 1fr); }
  .controls-strip > div { padding: 7px 9px; }
  .controls-strip span { font-size: 7px; }
  .controls-strip > div:nth-child(n+4) { display: none; }
  .modal-card { padding: 26px 22px; }
  .modal-actions { margin-top: 17px; }
  .end-stats { margin-top: 17px; }
}

@media (max-height: 650px) and (min-width: 761px) {
  .menu-content { padding-top: 16px; padding-bottom: 12px; }
  .tagline { margin-top: 12px; }
  .title-rule { margin: 10px 0 12px; }
  .holo-map { height: 110px; }
  .briefing-copy p { display: none; }
  .menu-frame { min-height: 520px; }
  .bottom-panel { height: calc(145px + var(--safe-bottom)); }
  .portrait-frame { width: 94px; height: 94px; }
  .command-button { min-height: 49px; }
  .command-button small { display: none; }
  .queue-row { display: none; }
}

