  } else {
    this.dom.selectionStats.innerHTML = [
      this.stat("DAMAGE", String(e.attack?.damage || 0)),
      this.stat("RANGE", String(e.attack?.range || 0)),
      this.stat("ARMOR", String(e.armor)),
