        }
      } else if (!unit.path.length) {
        const angle = angleTo(core.x, core.y, unit.x, unit.y);
        unit.path = this.nav.findPath(unit.x, unit.y, core.x + Math.cos(angle) * (core.radius + 20), core.y + Math.sin(angle) * (core.radius + 20));
