          if (core) this.orderMove(u, core.x + rand(-30, 30), core.y + rand(-30, 30));
        }
      }
    }
  }

  if (Math.floor(this.gameTime) % 2 === 0) this.recalcSupply(TEAM.PLAYER);
  if (this.stats.commands > 0 && this.gameTime > 8) {
